-- Synthetic accounts only. Always roll back, including their trigger-created profiles.
begin;
create temporary table community_test_ids(a uuid,b uuid,c uuid);
insert into community_test_ids values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant select on community_test_ids to authenticated;
insert into auth.users(id,email,is_anonymous) select a,'qa-a-'||a||'@example.invalid',false from community_test_ids union all select b,'qa-b-'||b||'@example.invalid',false from community_test_ids union all select c,'qa-c-'||c||'@example.invalid',false from community_test_ids;
update public.profiles set username='qa_'||substr(replace(id::text,'-',''),1,20) where id in(select a from community_test_ids union select b from community_test_ids union select c from community_test_ids);
insert into public.workspaces(user_id,data) select a,'{"owner":"A"}'::jsonb from community_test_ids union all select b,'{"owner":"B"}'::jsonb from community_test_ids;
create function pg_temp.assert_true(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',message;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub',a::text,true) from community_test_ids;
select pg_temp.assert_true((select count(*)=1 from public.profiles),'account profile RLS stays private');
select pg_temp.assert_true((select count(*)=1 from public.workspaces),'only own workspace is readable');
select pg_temp.assert_true((select data->>'owner'='A' from public.workspaces),'account A sees only account A data');
do $$declare affected integer; target uuid;begin
 select b into target from community_test_ids;
 update public.workspaces set data='{"owner":"intruder"}' where user_id=target;
 get diagnostics affected=row_count;perform pg_temp.assert_true(affected=0,'cross-account update denied');
 delete from public.workspaces where user_id=target;
 get diagnostics affected=row_count;perform pg_temp.assert_true(affected=0,'cross-account delete denied');
 select c into target from community_test_ids;
 begin insert into public.workspaces(user_id,data) values(target,'{}');raise exception 'FAILED: cross-account insert allowed';exception when insufficient_privilege then null;end;
 begin update public.workspaces set user_id=target;raise exception 'FAILED: workspace ownership transfer allowed';exception when insufficient_privilege then null;end;
end$$;
select pg_temp.assert_true((public.community_action('lookup',jsonb_build_object('query','qa_'||substr(replace(b::text,'-',''),1,20)))->'person'->>'id')=b::text,'exact username lookup') from community_test_ids;
select pg_temp.assert_true((public.community_action('lookup','{"query":"qa_"}')->'person')='null'::jsonb,'no partial directory search');
select pg_temp.assert_true(not(public.community_action('lookup',jsonb_build_object('query','qa-b-'||b||'@example.invalid'))->'person' ? 'email'),'lookup never returns email') from community_test_ids;
select public.community_action('share','{"item":{"key":"deck:test","kind":"deck","game":"mtg","title":"Shared fixture","secret":"PRIVATE","cards":[{"id":"one","name":"Fixture","qty":2,"manualValue":999,"notes":"PRIVATE"}]}}');
do $$declare target uuid;begin select b into target from community_test_ids;begin perform public.community_action('profile',jsonb_build_object('target',target));raise exception 'FAILED: stranger profile opened';exception when insufficient_privilege then null;end;end$$;
select public.community_action('request',jsonb_build_object('target',b)) from community_test_ids;
select public.community_action('request',jsonb_build_object('target',b)) from community_test_ids;
select pg_temp.assert_true(jsonb_array_length(public.community_action('overview')->'people')=1,'duplicate request is idempotent');
do $$declare target uuid;begin select b into target from community_test_ids;begin perform public.community_action('accept',jsonb_build_object('target',target));raise exception 'FAILED: sender accepted own request';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claim.sub',c::text,true) from community_test_ids;
do $$declare target uuid;begin select a into target from community_test_ids;begin perform public.community_action('accept',jsonb_build_object('target',target));raise exception 'FAILED: outsider accepted request';exception when insufficient_privilege then null;end;end$$;
select pg_temp.assert_true(jsonb_array_length(public.community_action('overview')->'people')=0,'outsider cannot read requests');
select set_config('request.jwt.claim.sub',b::text,true) from community_test_ids;
select pg_temp.assert_true((select count(*)=1 from public.workspaces),'account B sees only one workspace');
select pg_temp.assert_true((select data->>'owner'='B' from public.workspaces),'account B data remains intact after rejected writes');
select public.community_action('accept',jsonb_build_object('target',a)) from community_test_ids;
select pg_temp.assert_true((public.community_action('profile',jsonb_build_object('target',a))->'items'->0->>'title')='Shared fixture','accepted friend sees shared snapshot') from community_test_ids;
select pg_temp.assert_true(position('PRIVATE' in public.community_action('profile',jsonb_build_object('target',a))::text)=0,'private fields stripped on server') from community_test_ids;
select pg_temp.assert_true((select count(*)=1 from public.profiles),'friendship does not expose private account profiles');
select set_config('request.jwt.claim.sub',a::text,true) from community_test_ids;
select public.community_action('unshare','{"key":"deck:test"}');
select set_config('request.jwt.claim.sub',b::text,true) from community_test_ids;
select pg_temp.assert_true(jsonb_array_length(public.community_action('profile',jsonb_build_object('target',a))->'items')=0,'hiding immediately removes shared item') from community_test_ids;
select public.community_action('block',jsonb_build_object('target',a)) from community_test_ids;
select pg_temp.assert_true(jsonb_array_length(public.community_action('overview')->'people')=0,'block removes friendship');
select set_config('request.jwt.claim.sub',a::text,true) from community_test_ids;
do $$declare target uuid;begin select b into target from community_test_ids;begin perform public.community_action('request',jsonb_build_object('target',target));raise exception 'FAILED: blocked request allowed';exception when insufficient_privilege then null;end;begin perform public.community_action('profile',jsonb_build_object('target',target));raise exception 'FAILED: blocked profile opened';exception when insufficient_privilege then null;end;end$$;
select pg_temp.assert_true(public.community_action('lookup',jsonb_build_object('query','qa-b-'||b||'@example.invalid'))->'person'='null'::jsonb,'block removes lookup') from community_test_ids;
reset role;
select pg_temp.assert_true(not has_function_privilege('anon','public.community_action(text,jsonb)','EXECUTE'),'anonymous RPC denied');
select pg_temp.assert_true(not has_table_privilege('anon','public.workspaces','SELECT'),'anonymous workspace access denied');
select pg_temp.assert_true(not has_table_privilege('authenticated','community_private.showcase','SELECT'),'direct showcase access denied');
select 'PASS: exact lookup, no directory/email disclosure, mutual consent, outsider denial, private-field stripping, hide/block revocation and unchanged account RLS' as result;
rollback;
